  "goals",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
] as const;

export type ContextRecoverySectionName =
  (typeof CONTEXT_RECOVERY_SECTIONS)[number];

export type ContextRecoveryItem = string | number | boolean | null | {
  readonly [key: string]: unknown;
};

export interface WorkingContextSnapshot {
  readonly goals?: readonly ContextRecoveryItem[] | null;
  readonly unfinishedWork?: readonly ContextRecoveryItem[] | null;
  readonly outstandingWork?: readonly ContextRecoveryItem[] | null;
  readonly openWork?: readonly ContextRecoveryItem[] | null;
  readonly dependencies?: readonly ContextRecoveryItem[] | null;
  readonly recentEvidence?: readonly ContextRecoveryItem[] | null;
  readonly evidence?: readonly ContextRecoveryItem[] | null;
  readonly handoffChain?: readonly unknown[] | null;
  readonly handoffDepth?: number | null;
  readonly depth?: number | null;
}

export interface ContextPressureRecoveryOptions {
  /** Maximum number of items retained across all four sections. */
  readonly maxItems?: number;
  /** Alias for maxItems, retained for callers that describe it as a budget. */
  readonly itemBudget?: number;
  /** Maximum permitted handoff-chain depth. Equality is permitted. */
  readonly maxDepth?: number;
}

export interface ContextRecoverySection {
  readonly items: readonly ContextRecoveryItem[];
  readonly kept: number;
  readonly dropped: number;
}

export interface ContextPressureRecoveryResult {
  readonly status: "recovered" | "unknown" | "depth-exceeded";
  readonly complete: false;
  readonly digest: string;
  readonly sections?: {
    readonly goals: ContextRecoverySection;
    readonly unfinishedWork: ContextRecoverySection;
    readonly dependencies: ContextRecoverySection;
    readonly recentEvidence: ContextRecoverySection;
  };
  readonly counts?: {
    readonly total: number;
    readonly kept: number;
    readonly dropped: number;
  };
  readonly truncated?: boolean;
  readonly depth?: number;
  readonly maxDepth?: number;
  readonly reason?: "empty-snapshot" | "depth-exceeded";
}

const DEFAULT_MAX_ITEMS = 20;
const DEFAULT_MAX_DEPTH = 8;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function findWorkingContext(
  snapshot: WorkingContextSnapshot | null | undefined,
): WorkingContextSnapshot | null {
  if (!snapshot || !isObject(snapshot)) return null;
  const nested = snapshot.workingContext;
  if (nested && isObject(nested)) {
    return nested as WorkingContextSnapshot;
  }
  return snapshot;
}

function firstArray(
  snapshot: WorkingContextSnapshot,
  names: readonly string[],
): readonly ContextRecoveryItem[] {
  for (const name of names) {
    const value = snapshot[name];
    if (Array.isArray(value)) return value as readonly ContextRecoveryItem[];
  }
  return [];
}

function finiteNonNegativeInteger(value: unknown): number | null {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : null;
}

function snapshotDepth(snapshot: WorkingContextSnapshot): number {
  const explicit = finiteNonNegativeInteger(snapshot.handoffDepth);
  if (explicit !== null) return explicit;
  const genericDepth = finiteNonNegativeInteger(snapshot.depth);
  if (genericDepth !== null) return genericDepth;
  return Array.isArray(snapshot.handoffChain) ? snapshot.handoffChain.length : 0;
}

function canonicalize(value: unknown): unknown {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(canonicalize);
  const source = value as Record<string, unknown>;
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(source).sort()) {
    if (source[key] !== undefined) result[key] = canonicalize(source[key]);
  }
  return result;
}

function utf8Bytes(value: string): number[] {
  const bytes: number[] = [];
  for (let index = 0; index < value.length; index += 1) {
    let code = value.charCodeAt(index);
    if (code >= 0xd800 && code <= 0xdbff && index + 1 < value.length) {
      const low = value.charCodeAt(index + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        code = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
        index += 1;
      }
    }
    if (code <= 0x7f) {
      bytes.push(code);
    } else if (code <= 0x7ff) {
      bytes.push(0xc0 | (code >>> 6), 0x80 | (code & 0x3f));
    } else if (code <= 0xffff) {
      bytes.push(
        0xe0 | (code >>> 12),
        0x80 | ((code >>> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (code >>> 18),
        0x80 | ((code >>> 12) & 0x3f),
        0x80 | ((code >>> 6) & 0x3f),
        0x80 | (code & 0x3f),
      );
    }
  }
  return bytes;
}

function rotateRight(value: number, amount: number): number {
  return (value >>> amount) | (value << (32 - amount));
}

function sha256(input: string): string {
  const constants = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b,
    0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01,
    0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7,
    0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152,
    0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
    0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819,
    0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08,
    0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f,
    0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const initial = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f,
    0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ];
  const bytes = utf8Bytes(input);
  const bitLength = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let shift = 7; shift >= 0; shift -= 1) {
    bytes.push(Math.floor(bitLength / 2 ** (shift * 8)) & 0xff);
  }
  const hash = initial.slice();
  const words = new Array<number>(64);
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let index = 0; index < 16; index += 1) {
      const at = offset + index * 4;
      words[index] =
        (bytes[at] << 24) |
        (bytes[at + 1] << 16) |
        (bytes[at + 2] << 8) |
        bytes[at + 3];
    }
    for (let index = 16; index < 64; index += 1) {
      const s0 =
        rotateRight(words[index - 15], 7) ^
        rotateRight(words[index - 15], 18) ^
        (words[index - 15] >>> 3);
      const s1 =
        rotateRight(words[index - 2], 17) ^
        rotateRight(words[index - 2], 19) ^
        (words[index - 2] >>> 10);
      words[index] =
        (words[index - 16] + s0 + words[index - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = hash;
    for (let index = 0; index < 64; index += 1) {
      const sum1 = rotateRight(e, 6) ^ rotateRight(e, 11) ^ rotateRight(e, 25);
      const choice = (e & f) ^ (~e & g);
      const temp1 = (h + sum1 + choice + constants[index] + words[index]) >>> 0;
      const sum0 = rotateRight(a, 2) ^ rotateRight(a, 13) ^ rotateRight(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (sum0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    const next = [a, b, c, d, e, f, g, h];
    for (let index = 0; index < 8; index += 1) {
