}

function digestOf(value: unknown): string {
  return sha256(JSON.stringify(canonicalize(value)));
}

function section(items: readonly ContextRecoveryItem[]): ContextRecoverySection {
  return { items: items.slice(), kept: items.length, dropped: 0 };
}

/**
 * Projects a bounded, deterministic recovery summary from a Working Context
 * snapshot. The input is never mutated. A depth failure deliberately omits
 * sections rather than partially projecting a possibly cyclic handoff chain.
 */
export function projectWorkingContextRecovery(
  snapshot: WorkingContextSnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {},
): ContextPressureRecoveryResult {
  const maxDepth = finiteNonNegativeInteger(options.maxDepth) ?? DEFAULT_MAX_DEPTH;
  const configuredBudget = finiteNonNegativeInteger(options.maxItems);
  const budget =
    configuredBudget ??
    finiteNonNegativeInteger(options.itemBudget) ??
    DEFAULT_MAX_ITEMS;
  const workingContext = findWorkingContext(snapshot);

  if (!workingContext) {
    return {
      status: "unknown",
      complete: false,
      digest: digestOf({ status: "unknown", complete: false }),
      reason: "empty-snapshot",
    };
  }

  const depth = snapshotDepth(workingContext);
  if (depth > maxDepth) {
    return {
      status: "depth-exceeded",
      complete: false,
      digest: digestOf({
        status: "depth-exceeded",
        complete: false,
        depth,
        maxDepth,
      }),
      depth,
      maxDepth,
      reason: "depth-exceeded",
    };
  }

  const sourceSections: readonly (readonly ContextRecoveryItem[])[] = [
    firstArray(workingContext, ["goals", "goal"]),
    firstArray(workingContext, [
      "unfinishedWork",
      "outstandingWork",
      "openWork",
    ]),
    firstArray(workingContext, ["dependencies", "dependency"]),
    firstArray(workingContext, ["recentEvidence", "evidence"]),
  ];
  const total = sourceSections.reduce(
    (count, items) => count + items.length,
    0,
  );
  if (total === 0) {
    return {
      status: "unknown",
      complete: false,
      digest: digestOf({ status: "unknown", complete: false }),
      reason: "empty-snapshot",
    };
  }

  let remaining = budget;
  const projected = sourceSections.map((items) => {
    const kept = items.slice(0, remaining);
    remaining -= kept.length;
    const dropped = items.length - kept.length;
    return { items: kept, kept: kept.length, dropped };
  });
  const kept = projected.reduce((count, item) => count + item.kept, 0);
  const dropped = projected.reduce((count, item) => count + item.dropped, 0);
  const body = {
    status: "recovered" as const,
    complete: false as const,
    sections: {
      goals: projected[0],
      unfinishedWork: projected[1],
      dependencies: projected[2],
      recentEvidence: projected[3],
    },
    counts: { total, kept, dropped },
    truncated: dropped > 0,
    depth,
    maxDepth,
  };
  return { ...body, digest: digestOf(body) };
}

export const projectContextPressureRecovery = projectWorkingContextRecovery;
export const recoverWorkingContext = projectWorkingContextRecovery;

/** Compatibility helper for callers that need just the digest. */
export function workingContextRecoveryDigest(
  snapshot: WorkingContextSnapshot | null | undefined,
  options: ContextPressureRecoveryOptions = {},
): string {
  return projectWorkingContextRecovery(snapshot, options).digest;
}
